<script>
  import { format } from "d3-format";
  import EditableRegressionPlot from "./EditableRegressionPlot.svelte";
  import ErrorHistoryPlot from "./ErrorHistoryPlot.svelte";
  import {
    DEFAULT_PRESENTATION_DATASET_INDEX,
    getPresetDataset,
    PRESET_DATASET_COUNT,
  } from "../lib/data.js";
  import {
    clamp,
    getMeanBaseline,
    getPlotDomains,
    runGradientDescentSteps,
    summarizeLoss,
  } from "../lib/model.js";

  const countFormatter = format(".3f");
  const parameterFormatter = format(".2f");
  const rateFormatter = format(".4f");
  const defaultXAxisLabel = "Temperature (C)";
  const defaultYAxisLabel = "Ice Creams Sold";

  let datasetIndex = DEFAULT_PRESENTATION_DATASET_INDEX;
  let points = getPresetDataset(datasetIndex);
  let model = getMeanBaseline(points);
  let learningRate = 0.002;
  let iteration = 0;
  let history = [{ iteration: 0, error: summarizeLoss(points, model, "mse").mean }];
  let mode = "fitting";
  let xAxisLabel = defaultXAxisLabel;
  let yAxisLabel = defaultYAxisLabel;
  let xAxisLimitInput = "";
  let yAxisLimitInput = "";
  let predictionX = 5;
  let settingsOpen = false;
  let preservedDomains = null;
  let showControls = true;

  $: currentError = summarizeLoss(points, model, "mse").mean;
  $: xAxisLimit = parseAxisLimit(xAxisLimitInput);
  $: yAxisLimit = parseAxisLimit(yAxisLimitInput);
  $: inferredXUpperBound = getInferredUpperBound(points, "x");
  $: predictionMax = xAxisLimit ?? inferredXUpperBound;
  $: predictionX = clamp(predictionX, 0, predictionMax);
  $: predictionY = model.bias + model.weight * predictionX;
  $: activeXMin = preservedDomains?.xDomain?.[0] ?? null;
  $: activeXMax = xAxisLimit ?? preservedDomains?.xDomain?.[1] ?? null;
  $: activeYMin = preservedDomains?.yDomain?.[0] ?? null;
  $: activeYMax = yAxisLimit ?? preservedDomains?.yDomain?.[1] ?? null;

  function parseAxisLimit(value) {
    const numericValue = Number(value);
    return Number.isFinite(numericValue) && numericValue > 0 ? numericValue : null;
  }

  function getInferredUpperBound(nextPoints, field) {
    const maximum = nextPoints.length
      ? Math.max(0, ...nextPoints.map((point) => point[field]))
      : 0;

    return Math.max(Math.ceil((maximum + Math.max(maximum * 0.15, 1)) * 10) / 10, 30);
  }

  function resetDemo(nextPoints = points) {
    model = getMeanBaseline(nextPoints);
    iteration = 0;
    history = [{ iteration: 0, error: summarizeLoss(nextPoints, model, "mse").mean }];
  }

  function initializePrediction(nextPoints = points) {
    predictionX = getInferredUpperBound(nextPoints, "x") / 2;
  }

  function handlePointsChange(event) {
    points = event.detail.points;
    preservedDomains = null;
    resetDemo(points);
    initializePrediction(points);
  }

  function setModel(field, value) {
    model = {
      ...model,
      [field]: Number(value),
    };
    iteration += 1;
    history = [...history, { iteration, error: summarizeLoss(points, model, "mse").mean }];
  }

  function newData() {
    datasetIndex = (datasetIndex + 1) % PRESET_DATASET_COUNT;
    points = getPresetDataset(datasetIndex);
    preservedDomains = null;
    resetDemo(points);
    initializePrediction(points);
    mode = "fitting";
  }

  function clearAllPoints() {
    preservedDomains = getPlotDomains(points, model, xAxisLimit, yAxisLimit);
    points = [];
    resetDemo(points);
    initializePrediction(points);
  }

  function loadDefaultDataset() {
    datasetIndex = DEFAULT_PRESENTATION_DATASET_INDEX;
    points = getPresetDataset(DEFAULT_PRESENTATION_DATASET_INDEX);
    preservedDomains = null;
    resetDemo(points);
    initializePrediction(points);
    mode = "fitting";
  }

  function runSteps(steps) {
    const result = runGradientDescentSteps({
      points,
      model,
      learningRate,
      steps,
      startingIteration: iteration,
    });

    model = result.model;
    iteration = result.iteration;
    history = [...history, ...result.history];
  }

  function enterPredictionMode() {
    initializePrediction(points);
    mode = "prediction";
  }

  function returnToFittingMode() {
    mode = "fitting";
  }
</script>

<section class="demo-shell">
  <div class="section-header">
    <div>
      <h2>Gradient Descent</h2>
      <p>
        This tab starts with the same dots, but now the computer helps adjust the line.
        Add or move points, <br>then use the step buttons to watch gradient descent improve the model little by little.
      </p>
    </div>
    <div class="header-actions">
      <button on:click={mode === "fitting" ? enterPredictionMode : returnToFittingMode}>
        {mode === "fitting" ? "Done Fitting!" : "Continue Fitting"}
      </button>
      <button class="secondary" on:click={() => (showControls = !showControls)}>
        {showControls ? "Hide Controls" : "Show Controls"}
      </button>
    </div>
  </div>

  <div class:collapsed={!showControls} class="demo-grid">
    {#if showControls}
      <aside class="control-panel">
      {#if mode === "fitting"}
        <div class="button-row">
          <button on:click={newData}>New Data</button>
          <button class="secondary" on:click={() => resetDemo(points)}>Reset to Avg.</button>
        </div>

        <div class="button-row">
          <button class="secondary" on:click={() => runSteps(1)}>1 Step</button>
          <button class="secondary" on:click={() => runSteps(25)}>25 Steps</button>
          <button class="secondary" on:click={() => runSteps(100)}>100 Steps</button>
        </div>

        <div class="stats-grid">
          <div class="stat-card">
            <p class="label">Iterations</p>
            <p class="value">{iteration}</p>
          </div>
          <div class="stat-card">
            <p class="label">Current MSE</p>
            <p class="value">{countFormatter(currentError)}</p>
          </div>
        </div>

        <label class="slider-block" for="gd-rate">
          <span>Learning Rate</span>
          <strong>{rateFormatter(learningRate)}</strong>
        </label>
        <input
          id="gd-rate"
          type="range"
          min="0.0005"
          max="0.005"
          step="0.0001"
          bind:value={learningRate}
        />

        <label class="slider-block" for="gd-bias">
          <span>Bias</span>
          <strong>{parameterFormatter(model.bias)}</strong>
        </label>
        <input
          id="gd-bias"
          type="range"
          min="-40"
          max="100"
          step="0.05"
          value={model.bias}
          on:input={(event) => setModel("bias", event.currentTarget.value)}
        />

        <label class="slider-block" for="gd-weight">
          <span>Weight</span>
          <strong>{parameterFormatter(model.weight)}</strong>
        </label>
        <input
          id="gd-weight"
          type="range"
          min="-6"
          max="8"
          step="0.01"
          value={model.weight}
          on:input={(event) => setModel("weight", event.currentTarget.value)}
        />
      {:else}
        <div class="prediction-card">
          <p class="label">Prediction Time</p>
          <p class="caption">Your model is locked in. Slide the x-value to see the line make a prediction.</p>
        </div>

        <label class="slider-block" for="gd-prediction-x">
          <span>Choose an x-value</span>
          <strong>{parameterFormatter(predictionX)}</strong>
        </label>
        <input
          id="gd-prediction-x"
          type="range"
          min="0"
          max={predictionMax}
          step="0.1"
          bind:value={predictionX}
        />

        <div class="stat-card">
          <p class="label">Model's Guess</p>
          <p class="value">{countFormatter(predictionY)}</p>
          <p class="label">When x = {parameterFormatter(predictionX)}</p>
        </div>
      {/if}

      <div class="equation-block">
        <p class="label">Current Model</p>
        <strong>y = {parameterFormatter(model.weight)}x + {parameterFormatter(model.bias)}</strong>
      </div>

      {#if mode === "fitting"}
        <details class="settings-panel" bind:open={settingsOpen}>
          <summary>Additional Setting</summary>
          <div class="settings-body">
            <div class="button-row settings-buttons">
              <button class="secondary" on:click={clearAllPoints}>Clear Data</button>
              <button class="secondary" on:click={loadDefaultDataset}>Load Default Dataset</button>
            </div>

            <div class="axis-grid">
              <label class="text-block" for="gd-x-label">
                <span>X-Axis Label</span>
                <input id="gd-x-label" type="text" bind:value={xAxisLabel} />
              </label>
              <label class="text-block" for="gd-y-label">
                <span>Y-Axis Label</span>
                <input id="gd-y-label" type="text" bind:value={yAxisLabel} />
              </label>
            </div>

            <div class="limits-row">
              <label class="text-block compact" for="gd-x-max">
                <span>X Max</span>
                <input id="gd-x-max" type="number" min="0" step="0.1" bind:value={xAxisLimitInput} />
              </label>
              <label class="text-block compact" for="gd-y-max">
                <span>Y Max</span>
                <input id="gd-y-max" type="number" min="0" step="0.1" bind:value={yAxisLimitInput} />
              </label>
            </div>
          </div>
        </details>
      {/if}
      </aside>
    {/if}

    <div class="visual-panel">
      <div class="plot-card">
        <EditableRegressionPlot
          points={points}
          model={model}
          residualStyle="none"
          xLabel={xAxisLabel || defaultXAxisLabel}
          yLabel={yAxisLabel || defaultYAxisLabel}
          xMin={activeXMin}
          xMax={activeXMax}
          yMin={activeYMin}
          yMax={activeYMax}
          editable={mode === "fitting"}
          showPrediction={mode === "prediction"}
          {predictionX}
          on:pointschange={handlePointsChange}
        />
      </div>

      <div class="plot-card">
        <ErrorHistoryPlot {history} />
      </div>
    </div>
  </div>
</section>

<style>
  .demo-shell {
    display: grid;
    gap: 1.5rem;
  }

  .section-header h2 {
    margin: 0 0 0.5rem;
  }

  .header-actions {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
    justify-content: end;
  }

  .section-header p {
    margin: 0;
    max-width: 52rem;
    line-height: 1.6;
  }

  .demo-grid {
    display: grid;
    grid-template-columns: minmax(300px, 360px) minmax(0, 1fr);
    gap: 1.25rem;
    align-items: start;
  }

  .demo-grid.collapsed {
    grid-template-columns: 1fr;
  }

  .control-panel,
  .plot-card {
    border: 1px solid rgba(22, 32, 42, 0.12);
    border-radius: 20px;
    background: rgba(255, 255, 255, 0.88);
    box-shadow: 0 10px 30px rgba(22, 32, 42, 0.06);
  }

  .control-panel {
    display: grid;
    gap: 1rem;
    padding: 1rem;
  }

  .visual-panel {
    display: grid;
    gap: 1rem;
  }

  .plot-card {
    padding: 1rem;
  }

  .button-row {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
  }

  button {
    border: 0;
    border-radius: 999px;
    padding: 0.75rem 1rem;
    font: inherit;
    font-weight: 600;
    background: #1b8cff;
    color: #fff;
    cursor: pointer;
  }

  button.secondary {
    background: rgba(22, 32, 42, 0.08);
    color: #16202a;
  }

  .stats-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
  }

  .stat-card,
  .equation-block {
    border-radius: 16px;
    background: rgba(53, 102, 77, 0.08);
    padding: 0.95rem 1rem;
  }

  .label {
    margin: 0;
    font-size: 0.85rem;
    color: rgba(22, 32, 42, 0.68);
  }

  .value {
    margin: 0.25rem 0 0;
    font-size: 1.8rem;
    font-weight: 700;
  }

  .slider-block {
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-weight: 600;
  }

  .text-block {
    display: grid;
    gap: 0.4rem;
    font-weight: 600;
    min-width: 0;
  }

  .text-block input {
    box-sizing: border-box;
    width: 100%;
    border: 1px solid rgba(22, 32, 42, 0.16);
    border-radius: 12px;
    padding: 0.55rem 0.75rem;
    font: inherit;
  }

  .text-block.compact input {
    max-width: 100%;
  }

  .prediction-card {
    border-radius: 16px;
    background: rgba(27, 140, 255, 0.08);
    padding: 0.95rem 1rem;
  }

  .settings-panel {
    border: 1px solid rgba(22, 32, 42, 0.1);
    border-radius: 16px;
    background: rgba(22, 32, 42, 0.03);
    padding: 0.2rem 0.85rem 0.85rem;
  }

  .settings-panel summary {
    cursor: pointer;
    font-weight: 700;
    padding: 0.65rem 0 0.4rem;
  }

  .settings-body {
    display: grid;
    gap: 0.85rem;
    padding-top: 0.35rem;
  }

  .settings-buttons {
    justify-content: start;
  }

  .axis-grid {
    display: grid;
    grid-template-columns: minmax(0, 1fr);
    gap: 0.75rem;
  }

  .limits-row {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 0.75rem;
  }

  input[type="range"] {
    width: 100%;
  }

  @media (max-width: 960px) {
    .demo-grid {
      grid-template-columns: 1fr;
    }
  }
</style>