import presentationDataset from "../presentationDataset.json";

const presetSource = presentationDataset.datasets;

export const PRESET_DATASET_COUNT = presetSource.length;
export const DEFAULT_PRESENTATION_DATASET_INDEX = presentationDataset.defaultDatasetIndex;

export function clonePoints(points) {
  return points.map((point) => ({ x: point.x, y: point.y }));
}

export function getPresetDataset(index = DEFAULT_PRESENTATION_DATASET_INDEX) {
  const normalizedIndex =
    ((index % PRESET_DATASET_COUNT) + PRESET_DATASET_COUNT) %
    PRESET_DATASET_COUNT;

  return clonePoints(presetSource[normalizedIndex]);
}